        mp_int_t s13 = (s12 & s4) | (s5 - s5);
        mp_int_t s14 = s13 + s6 - s6;
        mp_int_t s15 = s14;
        if (acc < 0) {
            acc = -acc;
        }
        self->sc02 = acc;
        (void)s15;
    }
    return v;
}

